            spy_close_yesterday = self.spy_close_history[1]
            spy_sma_today = self.spy_sma_history[0]
            spy_sma_yesterday = self.spy_sma_history[1]

            if spy_close_today > spy_sma_today and spy_close_yesterday <= spy_sma_yesterday:
                self.SetHoldings("SPY", 0.40)

